 $('render-mode').textContent=state.map?'RÉFÉRENTIEL GALACTIQUE · POSITIONS EN 3D':state.relativistic?'VISION RELATIVISTE · ABERRATION + DOPPLER':'VISION INTUITIVE · DIRECTIONS GÉOMÉTRIQUES';
 const local=!!o&&renderer?.local&&renderer?.localId===o.id;$('local-tools').hidden=!local||state.map;$('science-color').hidden=!local||!['nebula','pillars','cluster'].includes(o?.type);$('context-kicker').textContent=local?(o.kind||labels[o.type]||'OBSERVATION LOCALE').toUpperCase():'ESPACE INTERSTELLAIRE';$('context-title').textContent=local?o.name:state.ap?'Cap sur '+state.ap.name:o?'Prochain horizon : '+o.name:'Le voyage t’appartient.';$('context-text').textContent=local?'À '+length(r)+' du centre · '+(o.type==='blackhole'?'rayons lumineux dans un modèle de Schwarzschild':'vue rapprochée reconstituée'):state.ap?'Navigation engagée. Reprends les commandes à tout moment.':'Glisse pour tourner le nez. Poussée pour partir, inertie pour continuer.';
